-- A sorted grouping's input sort holds the grouping keys and each column
-- its aggregates read, and spills under a small work_mem as PostgreSQL's
-- tuplesort does. A key the input computes prints as the input's output,
-- parenthesized. A limit over an ORDER BY the grouping's key order
-- satisfies stops the sort early.
CREATE TABLE g4 (i int, j int, v text);
INSERT INTO g4 SELECT i, i % 7, 'v' || i FROM generate_series(1, 8000) i;
ANALYZE g4;
SET work_mem = '64kB';
EXPLAIN SELECT i % 2000, count(*) FROM g4 GROUP BY 1;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 2000, count(*) FROM g4 GROUP BY 1;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 2000, max(v) FROM g4 GROUP BY 1;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 2000, max(v), sum(i) FROM g4 GROUP BY 1;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 100, count(v) FILTER (WHERE i > 5) FROM g4 GROUP BY 1;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 2000, max(v) FROM g4 GROUP BY 1 ORDER BY 1 LIMIT 3;
SELECT i % 2000, max(v) FROM g4 GROUP BY 1 ORDER BY 1 LIMIT 3;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 2000, max(v) FROM g4 GROUP BY 1 ORDER BY 1 DESC LIMIT 3;
SELECT i % 2000, max(v) FROM g4 GROUP BY 1 ORDER BY 1 DESC LIMIT 3;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 2000, max(v) FROM g4 GROUP BY 1 HAVING max(v) > 'v5' ORDER BY 1 LIMIT 3;
SELECT i % 2000, max(v) FROM g4 GROUP BY 1 HAVING max(v) > 'v5' ORDER BY 1 LIMIT 3;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT j, i % 500, min(v) FROM g4 GROUP BY 1, 2 ORDER BY 1 LIMIT 4;
SELECT j, i % 500, min(v) FROM g4 GROUP BY 1, 2 ORDER BY 1, 2 LIMIT 4;
SET work_mem = '4MB';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 2000, max(v) FROM g4 GROUP BY 1;
SET enable_hashagg = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 2000, max(v) FROM g4 GROUP BY 1;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT i % 20, string_agg(v, ',') FROM g4 GROUP BY 1;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT j, count(*) FROM g4 GROUP BY 1 ORDER BY 1 LIMIT 2;
DROP TABLE g4;
